/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v933',
  pack: 'THREE GOLD-NATIVE STRATEGIES ON GOLD SCALP AND GOLD SWING, ASKED FOR, AND ADDED ON THE TERMS THE EVIDENCE SETS. The prior is against more detectors: this desk already runs 78 OMNIGOLD mechanics and S0-S66 across Parts 4-9, hg-v922 measured that NOTHING either gold desk ranks by separates outcomes on four disjoint windows at both fill bounds, and hg-v925 measured the cohort freed by relaxing the evidence gate at 30.5% against a 33.3% breakeven. So the discipline is the pack, not the count. WHAT IS NEW, and each reads gold structure nothing in the catalog did. goldfix: the LBMA London fix fade. Gold is benchmarked twice a day at 10:30 and 15:00 LONDON LOCAL - the price the physical market clears against - and the session tables here cover Asia, London open and the NY overlap while leaving the two auctions inside them unmarked. It fades a run-in that drifted at least 0.8x ATR into the auction and closed back through its midpoint; a drift that simply continues mints NOTHING, because that is a trend and the desk has plenty of ways to read one. DST-aware through Intl, and it computes London time itself rather than depending on a helper that may not be loaded - the first version did, and in any context without indicators2.js the detector was silently dead, which looks exactly like a quiet market. golddxy: dollar divergence. Gold is priced in dollars so the two normally move inversely; the desk already holds the dollar leg and uses it ONLY as a one-way veto. The ANOMALY - both legs moving together with real magnitude - is the more informative state and was not read at all. Deliberately a continuation read, not a fade. Returns null with no dollar rows rather than assuming a correlation. goldround: round-dollar rejection at 100/50/25/10. OMNIGOLD has had ROUND-MAGNET since it was built and the two tabs a trader actually works from never did. The WICK-REJECTION half only - the magnet half is a target, not a trigger, and issuing an entry for it would invent a trigger the tape never gave. BARS ONLY, so none can be UNCHECKED for want of a feed. THEY MINT DEMOTED. A new mechanic has no measured record and this desk does not let an unmeasured setup lead - the same rule hgOgSiblingRecordNote applies to never-observed OMNIGOLD mechanics. They paint with full levels and reasoning, carry a NO RECORD stamp and a card note distinguishing absence of evidence from evidence of absence, and cannot be MOST PROBABLE until a bake gives them one. hgGoldExtraSetPromotable(true) lifts it, deliberately one explicit call and not a default. THEY ARE NOT REGISTERED AS OMNIGOLD MECHANICS, and that is not an oversight: hg-v923 showed registering one WIDENS the Sidak family bar for every existing mechanic, 77 to 78 moving it 3.2091 to 3.2128 sigma, so three more would make every OTHER mechanic promotion bar stricter on a desk where nothing currently clears it. The ask was GOLD SCALP and GOLD SWING and that is exactly where these live. MEASURED EFFECT on the real mint, 120 scans through the shipped goldScalpSetups: candidates 55 to 100, 45 of them goldround, ZERO throws, and the lead count UNCHANGED at 10 - so the board roughly doubles without a single gate loosening and without an unmeasured setup being crowned. No threshold moves. Tests: tests/test-gold-extra-strategies.mjs (56 assertions); 11 of 11 mutations caught after a first run left five survivors - three real gaps in my own fixtures and two mutations of mine too inert to test anything, which are recorded as dropped rather than counted as passes',
  built: '2026-09-22T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
